import pytest

from bedrock_protocol import v975, v1001, v2168

VERSIONS = [v975, v1001, v2168]

# generated by gophertunnel 6353c49:
# packet.MobEquipment{EntityRuntimeID: 7, InventorySlot: 2, HotBarSlot: 2, WindowID: 0}
V1001_AIR = bytes.fromhex("070000000000000000020200")

# generated by gophertunnel 6353c49:
# packet.MobEquipment{EntityRuntimeID: 7, NewItem: protocol.ItemInstance{StackNetworkID: 9,
#   Stack: protocol.ItemStack{ItemType: protocol.ItemType{NetworkID: 5, MetadataValue: 3}, Count: 1}},
#   InventorySlot: 2, HotBarSlot: 2, WindowID: 0}
V1001_HELMET = bytes.fromhex("070500010003010012000a00000000000000000000020200")

# generated by gophertunnel b8bd735:
# packet.MobEquipment{EntityRuntimeID: 7, InventorySlot: 2, HotBarSlot: 2, WindowID: 0}
V2168_AIR = bytes.fromhex("070000000000000000020200")

# generated by gophertunnel b8bd735:
# packet.MobEquipment{EntityRuntimeID: 7, NewItem: protocol.ItemInstance{StackNetworkID: 9,
#   Stack: protocol.ItemStack{ItemType: protocol.ItemType{NetworkID: 5, MetadataValue: 3}, Count: 1}},
#   InventorySlot: 2, HotBarSlot: 2, WindowID: 0}
V2168_HELMET = bytes.fromhex("0705000100030112000a00000000000000000000020200")

EMPTY_ITEM_BLOB = "\x00" * 10

GOLDENS = [
    pytest.param(
        v975.MobEquipmentPacket(runtime_id=7, slot=2, selected_slot=2, container_id=v975.ContainerID.INVENTORY),
        V1001_AIR,
        id="v975-air",
    ),
    pytest.param(
        v1001.MobEquipmentPacket(runtime_id=7, slot=2, selected_slot=2, container_id=v1001.ContainerID.INVENTORY),
        V1001_AIR,
        id="v1001-air",
    ),
    pytest.param(
        v1001.MobEquipmentPacket(
            runtime_id=7,
            item=v1001.SerializedNetworkItemStackDescriptor(
                id=5,
                stack_size=1,
                aux_value=3,
                net_id_variant=v1001.ItemStackNetId(raw_id=9),
                user_data_buffer=EMPTY_ITEM_BLOB,
            ),
            slot=2,
            selected_slot=2,
            container_id=v1001.ContainerID.INVENTORY,
        ),
        V1001_HELMET,
        id="v1001-helmet",
    ),
    pytest.param(
        v2168.MobEquipmentPacket(runtime_id=7, slot=2, selected_slot=2, container_id=v2168.ContainerID.INVENTORY),
        V2168_AIR,
        id="v2168-air",
    ),
    pytest.param(
        v2168.MobEquipmentPacket(
            runtime_id=7,
            item=v2168.SerializedNetworkItemStackDescriptor(
                id=5,
                stack_size=1,
                aux_value=3,
                net_id_variant=9,
                user_data_buffer=EMPTY_ITEM_BLOB,
            ),
            slot=2,
            selected_slot=2,
            container_id=v2168.ContainerID.INVENTORY,
        ),
        V2168_HELMET,
        id="v2168-helmet",
    ),
]


@pytest.mark.parametrize("version", VERSIONS)
def test_mob_equipment_is_packet_31(version):
    assert version.PACKETS[31] is version.MobEquipmentPacket


def test_mob_equipment_is_one_shape_across_975_and_1001():
    assert v975.MobEquipmentPacket is v1001.MobEquipmentPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_mob_equipment_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_mob_equipment_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_mob_equipment_is_the_same_bytes_across_1001_and_2168_without_a_net_id():
    assert V2168_AIR == V1001_AIR


def test_mob_equipment_net_id_is_one_byte_shorter_at_2168():
    assert len(V2168_HELMET) + 1 == len(V1001_HELMET)


def test_mob_equipment_1001_body_leaves_trailing_bytes_at_2168():
    with pytest.raises(ValueError, match="trailing bytes"):
        v2168.MobEquipmentPacket.from_bytes(V1001_HELMET)


def test_mob_equipment_2168_body_is_rejected_at_1001():
    with pytest.raises(ValueError, match="at byte"):
        v1001.MobEquipmentPacket.from_bytes(V2168_HELMET)
